/**
 * @file labs/mean-square-boundary/step-eigenbasis-lyapunov-g3.gen.ts
 * @description Generated by `scripts/generate-lyapunov-step-kernels.ts` (do not edit): one renormalised linearised
 * heavy-ball step for 3 step sizes sharing one scaled minibatch deviation, on the row-major pair layout
 * (`stepEigenbasisLyapunovG3`). Same operations per state as `stepEigenbasisLyapunovGeneral`; `x`, `xPrev`, `r` hold the
 * states one after the other (`n` entries each).
 * @cold
 */
import { fdlibmLog } from '../../src/math/index.ts';

export function stepEigenbasisLyapunovG3(
  sum: Float64Array,
  curvature: Float64Array,
  x: Float64Array,
  xPrev: Float64Array,
  r: Float64Array,
  n: number,
  beta: number,
  etas: Float64Array,
  logs: Float64Array,
  recordLog: boolean,
): void {
  const o1 = Math.imul(1, n);
  const o2 = Math.imul(2, n);
  const eta0 = etas[0]!;
  const eta1 = etas[1]!;
  const eta2 = etas[2]!;
  for (let a = 0; a < n; (a = (a + 1) | 0)) {
    const ca = curvature[a]!;
    r[a] = ca * x[a]!;
    r[(o1 + a) | 0] = ca * x[(o1 + a) | 0]!;
    r[(o2 + a) | 0] = ca * x[(o2 + a) | 0]!;
  }
  let p = 0;
  for (let a = 0; a < n; (a = (a + 1) | 0)) {
    const vd = sum[p]!;
    p = (p + 1) | 0;
    const xa0 = x[a]!;
    const xa1 = x[(o1 + a) | 0]!;
    const xa2 = x[(o2 + a) | 0]!;
    let ra0 = r[a]! + vd * xa0;
    let ra1 = r[(o1 + a) | 0]! + vd * xa1;
    let ra2 = r[(o2 + a) | 0]! + vd * xa2;
    for (let c = (a + 1) | 0; c < n; (c = (c + 1) | 0)) {
      const v = sum[p]!;
      p = (p + 1) | 0;
      ra0 += v * x[c]!;
      r[c] = r[c]! + v * xa0;
      ra1 += v * x[(o1 + c) | 0]!;
      r[(o1 + c) | 0] = r[(o1 + c) | 0]! + v * xa1;
      ra2 += v * x[(o2 + c) | 0]!;
      r[(o2 + c) | 0] = r[(o2 + c) | 0]! + v * xa2;
    }
    r[a] = ra0;
    r[(o1 + a) | 0] = ra1;
    r[(o2 + a) | 0] = ra2;
  }
  let nrm0 = 0.0;
  let nrm1 = 0.0;
  let nrm2 = 0.0;
  for (let k = 0; k < n; (k = (k + 1) | 0)) {
    const k0 = k;
    const cur0 = x[k0]!;
    const next0 = cur0 + beta * (cur0 - xPrev[k0]!) - eta0 * r[k0]!;
    xPrev[k0] = cur0;
    x[k0] = next0;
    nrm0 += next0 * next0 + cur0 * cur0;
    const k1 = (o1 + k) | 0;
    const cur1 = x[k1]!;
    const next1 = cur1 + beta * (cur1 - xPrev[k1]!) - eta1 * r[k1]!;
    xPrev[k1] = cur1;
    x[k1] = next1;
    nrm1 += next1 * next1 + cur1 * cur1;
    const k2 = (o2 + k) | 0;
    const cur2 = x[k2]!;
    const next2 = cur2 + beta * (cur2 - xPrev[k2]!) - eta2 * r[k2]!;
    xPrev[k2] = cur2;
    x[k2] = next2;
    nrm2 += next2 * next2 + cur2 * cur2;
  }
  const nu0 = Math.sqrt(nrm0);
  const nu1 = Math.sqrt(nrm1);
  const nu2 = Math.sqrt(nrm2);
  if (recordLog) {
    logs[0] = logs[0]! + fdlibmLog(nu0);
    logs[1] = logs[1]! + fdlibmLog(nu1);
    logs[2] = logs[2]! + fdlibmLog(nu2);
  }
  const inv0 = 1.0 / nu0;
  const inv1 = 1.0 / nu1;
  const inv2 = 1.0 / nu2;
  for (let k = 0; k < n; (k = (k + 1) | 0)) {
    const k0 = k;
    x[k0] = x[k0]! * inv0;
    xPrev[k0] = xPrev[k0]! * inv0;
    const k1 = (o1 + k) | 0;
    x[k1] = x[k1]! * inv1;
    xPrev[k1] = xPrev[k1]! * inv1;
    const k2 = (o2 + k) | 0;
    x[k2] = x[k2]! * inv2;
    xPrev[k2] = xPrev[k2]! * inv2;
  }
}
